mapper.insert:
INSERT INTO expense_project_approval(tenant_id,report_id,round_no,application_id,application_version,financial_version,
    definition_id,process_key,definition_version,rule_version,node_id,precheck_id,precheck_version,catalog_version,has_projects,submitted_at,snapshot_json)
SELECT e.tenant_id,e.id,#{roundNo},a.id,a.version,e.version,d.id,d.process_key,d.version,#{ruleVersion},#{nodeId},c.id,c.version,#{catalogVersion},#{hasProjects},#{submittedAt},#{stateJson}
FROM expense_report e JOIN approval_application a ON a.tenant_id=e.tenant_id AND a.id=e.application_id
JOIN approval_definition d ON d.tenant_id=a.tenant_id AND d.process_key=a.process_key AND d.version=a.definition_version
JOIN expense_precheck_job c ON c.tenant_id=e.tenant_id AND c.report_id=e.id AND c.application_id=a.id AND c.employee_id=e.employee_id
WHERE e.tenant_id=#{tenantId} AND e.id=#{reportId} AND a.id=#{applicationId} AND e.employee_id=#{employeeId} AND e.version=#{financialVersion} AND a.version=#{applicationVersion} AND e.current_round_no=#{currentRoundNo}
    AND a.status IN ('DRAFT','RETURNED','WITHDRAWN') AND a.business_type='EXPENSE' AND a.business_id=e.id
    AND (CASE WHEN a.status='DRAFT' THEN a.round_no ELSE a.round_no+1 END)=#{roundNo15}
    AND d.id=#{definitionId} AND d.process_key=#{processKey} AND d.version=#{definitionVersion} AND d.status='PUBLISHED'
    AND c.id=#{id} AND c.version=#{precheckVersion} AND c.status='READY' AND c.application_version=#{expectedApplicationVersion} AND c.financial_version=#{expectedFinancialVersion}
